namespace Packmaster.PackmasterCode.Packs;

/// <summary>
/// The card that represents a pack in the draft grid and pack lists (StS1 PackPreviewCard).
/// One subclass per pack, generated by tools/gen_cards.py. Unplayable, Token rarity, hidden from the library,
/// so it never shows up in rewards. Art is the StS1 pack art (cards/{PackId}.png).
/// Loc: PACKMASTER-{PACK}_PREVIEW.title/.description in cards.json (generated from the pack's UIstrings).
/// </summary>
public abstract class PackPreviewCard : Cards.PackmasterCard
{
    protected PackPreviewCard() : base(0, CardType.Skill, CardRarity.Token, TargetType.None, showInCardLibrary: false)
    {
        WithKeyword(CardKeyword.Unplayable);
    }

    public abstract string PackId { get; }

    public override string ArtId => PackId;

    public PackmasterPack? Pack => PackRegistry.Get(PackId);

    protected override Task OnPlay(PlayerChoiceContext ctx, CardPlay play) => Task.CompletedTask;
}
